-- The Jarvis browser: runs where Jarvis looks around (and clicks safe buttons) inside a site Luke named. Only Jarvis's own short summary and step log are kept, never page contents.
CREATE TABLE browse_runs (id TEXT PRIMARY KEY, site TEXT NOT NULL, goal TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('starting','waiting_login','running','done','stopped','failed')), steps INTEGER NOT NULL DEFAULT 0, cost_micro INTEGER NOT NULL DEFAULT 0, summary TEXT NOT NULL DEFAULT '', error TEXT, log TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
